WITH scored AS (SELECT *, AVG(monthly_fee) OVER (PARTITION BY MONTH(end_date), status) AS end_date_month_avg_monthly_fee, LAST_VALUE(monthly_fee, TRUE) OVER (PARTITION BY YEAR(end_date), customer_id ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee, ROW_NUMBER() OVER (PARTITION BY status ORDER BY end_date, id) AS row_seq, SUM(monthly_fee) OVER (ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_monthly_fee, AVG(monthly_fee) OVER (PARTITION BY plan ORDER BY end_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS monthly_fee_avg_2 FROM subscriptions) SELECT DATE_TRUNC('WEEK', end_date) AS week_start, SIZE(COLLECT_SET(plan)) AS num_plans, SIZE(COLLECT_SET(plan)) AS num_plans_2, COUNT_IF(status = 'EXPIRED') AS expired_events, SIZE(COLLECT_SET(status)) AS num_status, APPROX_PERCENTILE(end_date_month_avg_monthly_fee, ARRAY(0.25, 0.5, 0.75)) AS end_date_month_avg_monthly_fee_quartiles, SUM(CASE WHEN status = 'ACTIVE' THEN row_seq ELSE 0 END) AS active_row_seq FROM scored GROUP BY 1 ORDER BY num_plans_2 DESC
